import Model from 'flarum/common/Model';
export default class DiscussionSummary extends Model {
  contentHtml() {
    return Model.attribute('contentHtml').call(this);
  }
  model() {
    return Model.attribute('model').call(this);
  }
  createdAt() {
    return Model.attribute('createdAt', Model.transformDate).call(this);
  }
  postCount() {
    return Model.attribute('postCount').call(this);
  }
  newReplyCount() {
    return Model.attribute('newReplyCount').call(this);
  }
  canDelete() {
    return Model.attribute('canDelete').call(this);
  }
  discussion() {
    return Model.hasOne('discussion').call(this);
  }
}
flarum.reg.add('datlechin-ai-summarize', 'common/models/DiscussionSummary', DiscussionSummary);